            accn=r.get('identifier',[{}])[0].get('value')
            notes=' | '.join(n['text'] for n in r.get('note',[]))
            out.append(f"  [{e}] OBS {i} {r['code']['text']} status={r['status']} coll={r.get('effectiveDateTime')} issued={r.get('issued')} val={r.get('valueString')!r} acc={accn} spec={sp} note={notes}")
