        elif t=='MedicationAdministration':
            notes=' | '.join(n['text'] for n in r.get('note',[]))
            out.append(f"  [{e}] MEDADMIN {i} {r['medicationCodeableConcept']['text']} status={r['status']} dose={r.get('dosage',{}).get('text')} when={r.get('effectiveDateTime')} perf={[p['actor']['display'] for p in r.get('performer',[])]} note={notes}")
        elif t=='MedicationDispense':
            notes=' | '.join(n['text'] for n in r.get('note',[]))
            out.append(f"  [{e}] MEDDISP {i} {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} handed={r.get('whenHandedOver')} instr={[d['text'] for d in r.get('dosageInstruction',[])]} note={notes}")
        elif t=='DocumentReference':
            out.append(f"  [{e}] DOC {i} type={r['type']['text']} date={r.get('date')} author={[a['display'] for a in r.get('author',[])]} role={ext(r,'author-role')} status={r.get('docStatus')}")
            for ln in r['description'].split('\n'):
                out.append("        | "+ln)
        elif t=='Task':
            if r['status']=='requested':
                out.append(f"  [{e}] *** REQUEST {i} code={r['code']['coding'][0]['code']} focus={r.get('focus',{}).get('reference')} desc={r['description']}")
            else:
                out.append(f"  [{e}] ITEM {i} {r.get('businessStatus')} {r['code']['coding'][0]['code'] if r.get('code') else ''}")
        elif t=='Specimen':
            pass
        else:
            out.append(f"  [{e}] {t} {i} {json.dumps(r)[:300]}")
    # orphan specimens whose subject is pid but not referenced
    return '\n'.join(out)
if __name__=='__main__':
    for pid in sys.argv[1:]:
        print(render(pid)); print()
